// Recorta el análisis a lo que la IA necesita ver y arma el prompt.
const salida = $('Analizar stock vs ventas').first().json;

if (salida.exitCode !== 0) {
  throw new Error('El análisis falló: ' + (salida.stderr || 'sin detalle'));
}

const datos = JSON.parse(salida.stdout);
const TOPE = 25;

const limpiar = (filas = []) => filas.slice(0, TOPE).map(f => ({
  titulo: f.titulo || `[sin título] ${f.ean}`,
  stock: f.unidades_stock,
  eur: f.valor_eur,
  vendidas: f.vendidas_periodo,
  facturado: f.facturado_periodo,
  cobertura_meses: f.cobertura_meses,
}));

const compacto = {
  panorama: datos.panorama,
  segmentos: datos.segmentos,
  liquidar: limpiar(datos.liquidar),
  devolver: limpiar(datos.devolver),
  reponer: limpiar(datos.reponer),
  destacar: limpiar(datos.destacar),
  vigilar: limpiar(datos.vigilar),
};

const instrucciones = `Te paso el análisis de rotación de este mes. Los números ya están calculados y son correctos: no los recalcules ni los pongas en duda, usalos tal cual.

Tu tarea es escribir el informe mensual con esta estructura exacta:

## Lo que hay que hacer este mes
Tres acciones concretas, numeradas, en orden de impacto sobre la caja. Cada una con el título de los libros involucrados y el euro que mueve. Nada de "considerar" ni "evaluar": verbos de ejecución.

## Devolver y liquidar
Qué sacar de la estantería y por qué. Distinguí entre lo que conviene devolver al distribuidor y lo que conviene liquidar con descuento en tienda. Si ves un patrón temático o de sello en el stock muerto, decilo: eso corrige la política de compras hacia adelante.

## Reponer con urgencia
Títulos que venden y están agotados o casi. Cada día sin ellos es venta perdida. Ordenalos por lo que facturaron.

## Para el mostrador
Cinco títulos que tengan stock y rotación, para poner a la vista este mes. Una línea por título explicando por qué ese.

## Lo que aprendimos
Dos o tres observaciones sobre qué tipo de libro funciona y cuál no en esta librería. Esto alimenta las compras del mes que viene.

Reglas:
- Si un dato no está en el análisis, no lo inventes. Decí que falta.
- Nada de tablas de más de cuatro columnas.
- El informe entero, por debajo de 700 palabras.`;

const periodo = (datos.panorama.periodo_desde && datos.panorama.periodo_hasta)
  ? `Los datos de ventas van del ${datos.panorama.periodo_desde} al ${datos.panorama.periodo_hasta}.\n\n`
  : '';

return [{
  json: {
    panorama: datos.panorama,
    segmentos: datos.segmentos,
    prompt: instrucciones + '\n\n<analisis>\n' + periodo + JSON.stringify(compacto, null, 1) + '\n</analisis>',
  }
}];

