// Arma el markdown final con encabezado de contexto + informe de Claude,
// y arma también la versión HTML del mail (tablas, estilos en línea, sin imágenes).
const texto = $json.content[0].text;
const p = $('Armar el prompt').first().json.panorama;
const segmentos = $('Armar el prompt').first().json.segmentos || {};
const resumenListas = {
  liquidar: (segmentos.LIQUIDAR || {}).titulos || 0,
  devolver: (segmentos.DEVOLVER || {}).titulos || 0,
};

const hoy = new Date().toLocaleDateString('es-ES', {
  day: 'numeric', month: 'long', year: 'numeric'
});
const eur = n => Number(n).toLocaleString('es-ES', { maximumFractionDigits: 0 });

const cabecera = `# Informe de rotación — Librería Arenales
**${hoy}**

> €${eur(p.valor_stock_eur)} en estanterías · €${eur(p.capital_inmovilizado_eur)} sin vender en ${p.meses_analizados} meses · rotación ${p.rotacion_meses} meses (objetivo: ${p.rotacion_objetivo})
> **Caja recuperable estimada: €${eur(p.caja_recuperable_estimada_eur)}**

---

`;

const archivo = `informe_${new Date().toISOString().slice(0, 10)}.md`;

// --- versión HTML para el mail ---

const EMOJIS = {
  'Lo que hay que hacer este mes': '🎯',
  'Devolver y liquidar': '📦',
  'Reponer con urgencia': '⚠️',
  'Para el mostrador': '⭐',
  'Lo que aprendimos': '💡',
};

const inline = s => s
  .replace(/\*\*(.+?)\*\*/g, '<strong style="color:#004226;">$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>');

function notaListas(r) {
  return `<tr><td style="padding-bottom:12px;"><p style="margin:0;line-height:1.6;color:#6B6B6B;"><em>Las listas completas van adjuntas: ${r.liquidar} títulos para liquidar y ${r.devolver} para devolver, con EAN y precio, listas para imprimir.</em></p></td></tr>`;
}

function mdToHtml(md, resumenListas) {
  const bloques = [];
  let actual = [];
  for (const linea of md.split('\n')) {
    if (linea.trim() === '') {
      if (actual.length) { bloques.push(actual); actual = []; }
    } else {
      actual.push(linea);
    }
  }
  if (actual.length) bloques.push(actual);

  let html = '';
  let seccion = '';

  for (const bloque of bloques) {
    const primera = bloque[0].trim();

    if (primera === '---') continue;

    if (primera.startsWith('## ')) {
      if (seccion === 'Devolver y liquidar') html += notaListas(resumenListas);
      seccion = primera.slice(3).trim();
      const emoji = EMOJIS[seccion] || '📄';
      html += `<tr><td style="padding:16px 0 8px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
          <tr><td style="background:#004226;color:#ffffff;font-size:16px;font-weight:bold;padding:12px 16px;border-radius:8px;">${emoji} ${seccion}</td></tr>
        </table>
      </td></tr>`;
      continue;
    }

    if (bloque.every(l => l.trim().startsWith('|'))) {
      const filas = bloque
        .map(l => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim()));
      const encabezado = filas[0];
      const cuerpo = filas.slice(2); // se salta la fila separadora ---|---
      let tabla = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:13px;">';
      tabla += '<tr>' + encabezado.map(c => `<th style="background:#004226;color:#ffffff;text-align:left;padding:8px;border:1px solid #E8E6E2;">${inline(c)}</th>`).join('') + '</tr>';
      cuerpo.forEach((fila, i) => {
        const fondo = i % 2 === 0 ? '#ffffff' : '#F4F2EE';
        tabla += '<tr>' + fila.map(c => `<td style="background:${fondo};padding:8px;border:1px solid #E8E6E2;color:#2A2A2A;">${inline(c)}</td>`).join('') + '</tr>';
      });
      tabla += '</table>';
      html += `<tr><td style="padding-bottom:12px;">${tabla}</td></tr>`;
      continue;
    }

    if (/^\*\*\d+\./.test(primera) && seccion.toLowerCase().includes('hacer este mes')) {
      const titulo = inline(bloque[0]);
      const resto = inline(bloque.slice(1).join(' '));
      html += `<tr><td style="padding-bottom:12px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FBFAF8;border-left:3px solid #004226;">
          <tr><td style="padding:12px 16px;">
            <p style="margin:0 0 6px 0;line-height:1.6;color:#2A2A2A;">${titulo}</p>
            <p style="margin:0;line-height:1.6;color:#2A2A2A;">${resto}</p>
          </td></tr>
        </table>
      </td></tr>`;
      continue;
    }

    if (bloque.every(l => /^\d+\.\s/.test(l.trim()))) {
      const items = bloque.map(l => `<li style="margin-bottom:8px;line-height:1.6;color:#2A2A2A;">${inline(l.trim().replace(/^\d+\.\s/, ''))}</li>`).join('');
      html += `<tr><td style="padding-bottom:12px;"><ol style="margin:0;padding-left:20px;">${items}</ol></td></tr>`;
      continue;
    }

    if (bloque.every(l => /^[-*]\s/.test(l.trim()))) {
      const items = bloque.map(l => `<li style="margin-bottom:8px;line-height:1.6;color:#2A2A2A;">${inline(l.trim().replace(/^[-*]\s/, ''))}</li>`).join('');
      html += `<tr><td style="padding-bottom:12px;"><ul style="margin:0;padding-left:20px;">${items}</ul></td></tr>`;
      continue;
    }

    const parrafo = inline(bloque.join(' '));
    html += `<tr><td style="padding-bottom:12px;"><p style="margin:0;line-height:1.6;color:#2A2A2A;">${parrafo}</p></td></tr>`;
  }

  if (seccion === 'Devolver y liquidar') html += notaListas(resumenListas);

  return html;
}

const mesCap = (m => m.charAt(0).toUpperCase() + m.slice(1))(
  new Date().toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })
);

const cuerpoHtml = mdToHtml(texto, resumenListas);

const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FBFAF8;padding:24px 0;">
<tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:600px;max-width:100%;background:#ffffff;font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <tr><td style="background:#004226;padding:28px 24px;text-align:center;">
    <div style="color:#ffffff;font-size:20px;font-weight:bold;">Librería Arenales</div>
    <div style="color:#ffffff;font-size:15px;margin-top:4px;">Informe de rotación · ${mesCap}</div>
    <div style="color:#8FB3A0;font-size:12px;margin-top:8px;">Ventas del ${p.periodo_desde} al ${p.periodo_hasta}</div>
  </td></tr>
  <tr><td style="padding:20px 16px 4px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td width="50%" style="padding:6px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#E3EEE8;border-radius:8px;">
            <tr><td style="padding:16px;text-align:center;">
              <div style="font-size:26px;font-weight:bold;color:#004226;">€${eur(p.valor_stock_eur)}</div>
              <div style="font-size:11px;color:#6B6B6B;margin-top:4px;">en estanterías</div>
            </td></tr>
          </table>
        </td>
        <td width="50%" style="padding:6px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F8E9E8;border-radius:8px;">
            <tr><td style="padding:16px;text-align:center;">
              <div style="font-size:26px;font-weight:bold;color:#004226;">${p.pct_titulos_sin_venta}%</div>
              <div style="font-size:11px;color:#6B6B6B;margin-top:4px;">sin vender en ${p.meses_analizados} meses</div>
            </td></tr>
          </table>
        </td>
      </tr>
      <tr>
        <td width="50%" style="padding:6px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F8E9E8;border-radius:8px;">
            <tr><td style="padding:16px;text-align:center;">
              <div style="font-size:26px;font-weight:bold;color:#004226;">${p.rotacion_meses}</div>
              <div style="font-size:11px;color:#6B6B6B;margin-top:4px;">meses de rotación · objetivo ${p.rotacion_objetivo}</div>
            </td></tr>
          </table>
        </td>
        <td width="50%" style="padding:6px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#E3EEE8;border-radius:8px;">
            <tr><td style="padding:16px;text-align:center;">
              <div style="font-size:26px;font-weight:bold;color:#004226;">€${eur(p.caja_recuperable_estimada_eur)}</div>
              <div style="font-size:11px;color:#6B6B6B;margin-top:4px;">caja recuperable estimada</div>
            </td></tr>
          </table>
        </td>
      </tr>
    </table>
  </td></tr>
  <tr><td style="padding:8px 16px 8px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
      ${cuerpoHtml}
    </table>
  </td></tr>
  <tr><td style="background:#FBFAF8;color:#6B6B6B;font-size:11px;text-align:center;padding:16px;">
    Generado automáticamente el ${hoy}. Próximo informe: el día 1 del mes que viene.
  </td></tr>
</table>
</td></tr>
</table>`;

return [{
  json: { archivo, panorama: p, informe: cabecera + texto, html },
  binary: {
    data: {
      data: Buffer.from(cabecera + texto, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: archivo,
    }
  }
}];

const salida = $input.first().json;

if (salida.exitCode !== 0) {
  throw new Error('No se pudieron codificar los adjuntos: ' + (salida.stderr || 'sin detalle'));
}

const datos = JSON.parse(salida.stdout);
const binary = {};
for (const [clave, b64] of Object.entries(datos)) {
  binary[clave] = { data: b64, mimeType: 'text/csv', fileName: `${clave}.csv` };
}

return [{ json: {}, binary }];
